-- ---- Cuevas (CuevaDetalle) ----
INSERT INTO caves (slug, name, cave_type, description, short_description, address, phone, email, website, difficulty, tour_duration, opening_hours, highlights, price_adult, latitude, longitude, rating, image_url, gallery, status, published_at)
  SELECT 'tres-ojos', 'Los Tres Ojos', 'Cueva', 'Los Tres Ojos es un parque natural único que alberga tres lagos de agua dulce en cuevas de piedra caliza formadas hace millones de años. Este sitio arqueológico fue habitado por los taínos y hoy es uno de los destinos más visitados de Santo Domingo. Los tres lagos principales son: Aguas Azufradas, La Nevera y Los Zaramagullones. Un cuarto lago, El Lago de las Mujeres, es accesible mediante un pequeño bote.', 'Un sistema de tres lagos subterráneos de agua dulce dentro de una caverna de piedra caliza.', 'Parque Mirador del Este, Santo Domingo Este', '+1 809-788-7056', 'info@tresojos.gob.do', 'https://tresojos.gob.do', 'Fácil', '1-2 horas', '9:00 AM - 5:00 PM', '["Lago Aguas Azufradas","Lago La Nevera","Lago Los Zaramagullones","Lago de las Mujeres (acceso en bote)","Pasarelas panorámicas","Formaciones de estalactitas y estalagmitas"]'::jsonb, 100, 18.4679, -69.8612, 4.6, 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&h=600&fit=crop', '["https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1504893524553-b855bce32c67?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1519681393784-d120267933ba?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1432405972618-c6b0c635e16c?w=800&h=600&fit=crop"]'::jsonb, 'published', now()
  WHERE NOT EXISTS (SELECT 1 FROM caves WHERE slug = 'tres-ojos');
INSERT INTO caves (slug, name, cave_type, description, short_description, address, phone, email, website, difficulty, tour_duration, opening_hours, highlights, price_adult, latitude, longitude, rating, image_url, gallery, status, published_at)
  SELECT 'maravillas', 'Cueva de las Maravillas', 'Cueva', 'La Cueva de las Maravillas es un museo natural subterráneo que preserva una de las colecciones más importantes de arte rupestre taíno del Caribe. Con más de 500 pictografías y petroglifos, este sitio declarado Patrimonio de la Humanidad ofrece una ventana única a la cultura precolombina. El recorrido guiado de 240 metros incluye sistemas de iluminación modernos que realzan las obras sin dañarlas.', 'Galería de arte taíno subterráneo con más de 500 pictografías y petroglifos.', 'Carretera La Romana - San Pedro, San Pedro de Macorís', '+1 809-696-1797', 'info@cuevadelasmaravillas.com', 'https://cuevadelasmaravillas.com', 'Moderado', '1.5-2 horas', '9:00 AM - 5:00 PM (Cerrado los lunes)', '["500+ pictografías taínas","Petroglifos ancestrales","Formaciones de estalactitas","Museo interpretativo","Sendero elevado de 240m","Sistema de iluminación artística"]'::jsonb, 250, 18.4098, -69.0234, 4.8, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=600&fit=crop', '["https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1504893524553-b855bce32c67?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1519681393784-d120267933ba?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1432405972618-c6b0c635e16c?w=800&h=600&fit=crop"]'::jsonb, 'published', now()
  WHERE NOT EXISTS (SELECT 1 FROM caves WHERE slug = 'maravillas');
INSERT INTO caves (slug, name, cave_type, description, short_description, address, phone, email, website, difficulty, tour_duration, opening_hours, highlights, price_adult, latitude, longitude, rating, image_url, gallery, status, published_at)
  SELECT 'pomier', 'Reserva Antropológica El Pomier', 'Cueva', 'El Pomier es el sistema de cuevas con arte rupestre más importante del Caribe, declarado Patrimonio de la Humanidad por la UNESCO. Con 55 cuevas documentadas y más de 6,000 grabados y pinturas rupestres, representa el legado más completo de la cultura taína. El sitio requiere buena condición física ya que incluye escalada moderada y terreno irregular.', 'La capital prehistórica del Caribe con más de 50 cuevas y 6,000 grabados rupestres.', 'San Cristóbal, San Cristóbal', '+1 809-528-0000', 'reservas@pomier.gob.do', 'https://medioambiente.gob.do', 'Difícil', '3-4 horas', '8:00 AM - 4:00 PM', '["55 cuevas documentadas","6,000+ grabados rupestres","Pinturas ceremoniales taínas","Formaciones geológicas únicas","Murciélagos endémicos","Senderos de exploración"]'::jsonb, 500, 18.4167, -70.1, 4.9, 'https://images.unsplash.com/photo-519681393784-d120267933ba?w=800&h=600&fit=crop', '["https://images.unsplash.com/photo-519681393784-d120267933ba?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1504893524553-b855bce32c67?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1432405972618-c6b0c635e16c?w=800&h=600&fit=crop"]'::jsonb, 'published', now()
  WHERE NOT EXISTS (SELECT 1 FROM caves WHERE slug = 'pomier');
INSERT INTO caves (slug, name, cave_type, description, short_description, address, phone, email, website, difficulty, tour_duration, opening_hours, highlights, price_adult, latitude, longitude, rating, image_url, gallery, status, published_at)
  SELECT 'fun-fun', 'Cueva Fun Fun', 'Cueva', 'La Cueva Fun Fun es una de las experiencias de aventura más emocionantes del Caribe. El recorrido comienza con un descenso en rappel de 18 metros hacia las entrañas de la tierra, seguido de una caminata por un río subterráneo y la exploración de impresionantes formaciones de estalactitas y estalagmitas. El nombre ''Fun Fun'' proviene del sonido que hacen los murciélagos al volar.', 'Aventura extrema con rappel, río subterráneo y formaciones de estalactitas.', 'Rancho Capote, Hato Mayor', '+1 809-553-2818', 'info@ranchocapote.com', 'https://ranchocapote.com', 'Difícil', '4-5 horas', '8:00 AM - 2:00 PM', '["Rappel de 18 metros","Río subterráneo","Estalactitas milenarias","Colonia de murciélagos","Cabalgata incluida","Almuerzo típico dominicano"]'::jsonb, 95, 18.7667, -69.25, 4.9, 'https://images.unsplash.com/photo-1504893524553-b855bce32c67?w=800&h=600&fit=crop', '["https://images.unsplash.com/photo-1504893524553-b855bce32c67?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1519681393784-d120267933ba?w=800&h=600&fit=crop","https://images.unsplash.com/photo-1432405972618-c6b0c635e16c?w=800&h=600&fit=crop"]'::jsonb, 'published', now()
  WHERE NOT EXISTS (SELECT 1 FROM caves WHERE slug = 'fun-fun');

