INSERT INTO clinics (slug, name, clinic_type, address, description, image_url, phone, emergency_phone, email, website, specialties, services, certifications, languages, rating, review_count, is_24_hours, is_active, extras, status, published_at)
  SELECT 'centro-medico-punta-cana', 'Centro Médico Punta Cana', 'Hospital General', 'Blvd. Turístico del Este Km 28, Punta Cana', 'Centro Médico Punta Cana es un hospital de atención integral con tecnología de vanguardia y un equipo médico bilingüe especializado en atención a turistas. Contamos con servicios de emergencia 24/7, especialidades médicas y cirugías ambulatorias con los más altos estándares internacionales.', 'https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?w=1920&h=800&fit=crop', '+1 809 552 1506', '+1 809 552 1911', 'info@centromedicoPuntaCana.com', NULL, '["Emergencias 24/7","Cirugía Estética","Odontología","Cardiología","Traumatología","Medicina General"]'::jsonb, '["Emergencias 24 horas","Laboratorio clínico","Rayos X y Tomografía","Farmacia 24 horas","Ambulancia","Coordinación con seguros"]'::jsonb, '["JCI Accredited","ISO 9001","Turismo Médico RD"]'::jsonb, '["Español","Inglés","Francés","Alemán","Italiano"]'::jsonb, 4.8, 892, true, true, '{"location":"Punta Cana, La Altagracia","treatments":[{"name":"Consulta General","priceFrom":50,"currency":"USD"},{"name":"Emergencia","priceFrom":100,"currency":"USD"},{"name":"Cirugía Dental","priceFrom":200,"currency":"USD"},{"name":"Chequeo Ejecutivo","priceFrom":350,"currency":"USD"}],"testimonials":[{"name":"James W.","country":"USA","rating":5,"treatment":"Emergencia","comment":"Excellent care during my vacation emergency. Staff was professional and bilingual."},{"name":"Marie P.","country":"Canadá","rating":5,"treatment":"Dental","comment":"Had dental work done at a fraction of US costs. Modern facilities and great results."}],"hours":{"emergencies":"24/7","consultation":"8:00 AM - 6:00 PM","lab":"7:00 AM - 7:00 PM"},"nearbyHotels":["Excellence Punta Cana","Secrets Royal Beach","Hard Rock Hotel"]}'::jsonb, 'published', now()
  WHERE NOT EXISTS (SELECT 1 FROM clinics WHERE slug = 'centro-medico-punta-cana');

